#include <vector>
#include <memory>
#include <iostream>

class Resource { /* ... */ };

int main() {
    // Storing copies (Value Semantics)
    std::vector<int> v = {10};
    int x = v[0]; // x is a copy, modifying x doesn't affect v[0]

    // Storing pointers to avoid expensive copies and handle ownership
    // (Reference Semantics via Smart Pointer)
    std::vector<std::shared_ptr<Resource>> ptr_v;
    ptr_v.push_back(std::make_shared<Resource>());

    // std::vector<std::unique_ptr<int>> u_v; // Requires move semantics (C++11+)
}
